mapper.select:
SELECT
COUNT(DISTINCT t1.id) as total
FROM
safety_inspect_record t1
INNER JOIN safety_inspect_record_item t2 on t1.id = t2.record_id

    t2.error_value_flag = 1
    and ( t1.business_type != 'SMALL_ENGINEERING' OR t1.business_type IS NULL )

        and t2.item_tag in

            #{code}



        and t1.time >= #{query.period.begin}


        and t1.time <= #{query.period.end}


        and t1.market_tenant = #{query.marketTenant}
